INSERT INTO public.modelcatalog_configuration (id, software_version_id, model_configuration_id, label, description, keywords, usage_notes, has_component_location, has_implementation_script_location, has_software_image, has_model_result_table, has_region, calibration_interval, calibration_method, parameter_assignment_method, valid_until, author_id) VALUES ('https://w3id.org/okn/i/mint/37d17ee0-0ce6-4095-9f32-90c1b33859f2', 'https://w3id.org/okn/i/mint/cd1e357a-534f-4e47-8bb9-8d7789663ebf', NULL, 'Central Valley Hydrologic Model', 'CVHM Components 1. Geospatial Database A Geographic Information System (GIS) was used to compile, manage, store, and analyze the large quantities of data in the geospatial database needed to run the model, and to understand and visualize the data output. 2. Texture Model The texture model is key to understanding how water moves through the Central Valley groundwater system. Scientists developed the geologic texture model to describe the coarseness or fineness of valley-fill materials that make up the aquifer system, and then used it to estimate hydraulic properties for every cell in the model grid. To create the model, lithologic data from approximately 8,500 drillers'' logs of boreholes ranging in depth from 12 to 3,000 feet below land surface, along with other information, were compiled and analyzed. 3. Farm Process The complex hydrologic system of the Central Valley is simulated using the USGS hydrologic modeling software, MODFLOW. Combined with the Farm Process, MODFLOW simulates natural and human-induced water movement and consumption over the landscape and accounts for supply-constrained and demand-driven conjunctive use of surface and groundwater in agricultural, urban, and natural settings. For the Central Valley, the tool simulates unmetered historical pumping and surface-water deliveries for 21 water-balance regions for water years 1962 to 2003. 4. Numerical Model A numerical groundwater-flow model capable of being accurate at scales relevant to water-management decisions was developed for the Central Valley, California. The modeling software is MODFLOW2000 with the Farm Process (FMP).', 'Hydrology, Agriculture, Geospatial Database, Texture Model, Farm Process, Numerical Model', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://w3id.org/okn/i/mint/7ada3329-1e8b-41f0-9a5a-bd4d31e59827') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_configuration (id, software_version_id, model_configuration_id, label, description, keywords, usage_notes, has_component_location, has_implementation_script_location, has_software_image, has_model_result_table, has_region, calibration_interval, calibration_method, parameter_assignment_method, valid_until, author_id) VALUES ('https://w3id.org/okn/i/mint/399d051b-6562-4ce2-83eb-71bb38b83c8d', NULL, 'https://w3id.org/okn/i/mint/a57dafde-d855-4ed8-9eca-f8f50fa95635', 'GAM Capitan Reef Complex ', 'The groundwater availability model (GAM) includes comprehensive information on the Capitan Reef Complex Aquifer, such as recharge (amount of water entering the aquifer); geology and how that conveys into the framework of the model; rivers, lakes, and springs; water levels; aquifer properties; and pumping. This model has been calibrated to ensure that the model can reasonably reproduce past water levels and groundwater flows. Texas Water Development Board (TWDB). Capitan Reef Complex Aquifer Groundwater Availability Model Files, https://txwaterdatahub.org/dataset/capitan-reef-complex-aquifer-gam-files. 2025-09-03.', NULL, NULL, 'https://tapis.tapis.io/v3/apps/modflow-2005/0.0.6', NULL, NULL, NULL, 'https://w3id.org/okn/i/mint/Texas', NULL, NULL, 'Calibration', NULL, NULL) ON CONFLICT DO NOTHING;
