INSERT INTO public.modelcatalog_configuration (id, software_version_id, model_configuration_id, label, description, keywords, usage_notes, has_component_location, has_implementation_script_location, has_software_image, has_model_result_table, has_region, calibration_interval, calibration_method, parameter_assignment_method, valid_until, author_id) VALUES ('https://w3id.org/okn/i/mint/46fd5e0a-6819-4646-b468-9ba268364ccf', 'https://w3id.org/okn/i/mint/a5224a85-a259-40bd-88b2-9c1fdf277ea2', NULL, 'GHOST - Middle Cedar', 'The Middle Cedar River Watershed (MCWMA) is a 1.5M-acre watershed that spans parts of 10 counties in Eastern Iowa. It encompasses primarily the Iowan Surface landform, characterized by long, gently rolling hills and well-developed stream networks. The MCRW is part of the Cedar River Basin that stretches from Minnesota to Southeast Iowa, where it meets the Iowa River. The MCRW includes some of the richest farmland in the nation. Seventy-three percent of the land is dedicated to row crop agriculture and seed corn production. The MCRW also supports a substantial portion of Iowaâ€™s urban areas, including Cedar Rapids, Waterloo, and Cedar Falls.
INSERT INTO public.modelcatalog_configuration (id, software_version_id, model_configuration_id, label, description, keywords, usage_notes, has_component_location, has_implementation_script_location, has_software_image, has_model_result_table, has_region, calibration_interval, calibration_method, parameter_assignment_method, valid_until, author_id) VALUES ('https://w3id.org/okn/i/mint/47aed31f-7b5a-4d8a-a496-86065b0b9a1a', 'https://w3id.org/okn/i/mint/a5224a85-a259-40bd-88b2-9c1fdf277ea2', NULL, 'GHOST - Upper Iowa', 'The 1,000-square-mile (640,900 acres) Upper Iowa River originates in Minnesota, but 78% of its watershed is in Northeast Iowa. The Upper Iowa River Watershed (UIRW) is part of the Driftless Region of Iowa. Its karst topography features limestone bluffs that rise 250 to 450 feet above the valley floor, dozens of coldwater trout streams, nearly 3,000 sinkholes and waterfalls, and hundreds of springs. Cropland accounts for more than 40% of the watershed, which also includes grassland (35%) and hardwood forests (19%). The EPA and Iowa recognize the UIRW as a Priority Watershed. Iowa designates 244 miles of the Upper Iowa River as High-quality Resource Waters or High-quality Waters, and the Upper Iowa was among the initial rivers included in the National Wild and Scenic River System.
INSERT INTO public.modelcatalog_configuration (id, software_version_id, model_configuration_id, label, description, keywords, usage_notes, has_component_location, has_implementation_script_location, has_software_image, has_model_result_table, has_region, calibration_interval, calibration_method, parameter_assignment_method, valid_until, author_id) VALUES ('https://w3id.org/okn/i/mint/482ca564-f809-4879-b8ee-95f6ed525a24', 'https://w3id.org/okn/i/mint/d6d6b994-db7b-4320-ae5c-7cf22157d3a6', NULL, 'SWAT GRDC Workbench', 'This is a MINT integrated workbench developed as a container for building alternative SWAT initializations and the calibration of these models for Ethiopia and any other basin for which the Global Runoff Data Centre (GRDC) within Bundesanstalt für Gewässerkunde (German Federal Institute of Hydrology; https://www.bafg.de/) has daily data. The initialization builds weather forcing estimates using the FillMissWX tool to which automatically download all available Global Historical Climatology Network (GHCN) daily weather data filling the required weather records for SWAT with data using neighboring monitors data based on three estimation methods including IDW, IDEW, and closest available station. Calibrations for initialized basins are are performed using for all available GRDC pour point data aligned with the preprocessed GHCN weather data for the GRDC period or record using a evolutionary differential evolution algorithm DEoptim algorithm (Ardia et al., 2007; Mullen et al., 2011). SWAT Outputs are written to NetCDF-CF format files as well as PDF summary graphics for integration with other components of the MINT modeling framework. 
