INSERT INTO public.modelcatalog_configuration (id, software_version_id, model_configuration_id, label, description, keywords, usage_notes, has_component_location, has_implementation_script_location, has_software_image, has_model_result_table, has_region, calibration_interval, calibration_method, parameter_assignment_method, valid_until, author_id) VALUES ('https://w3id.org/okn/i/mint/57718a24-be82-4acd-9e07-bddba2f75738', 'https://w3id.org/okn/i/mint/49032802-8a68-4f6b-ac1b-5c0ce676e012', NULL, 'topoflow v3.6-3.0.0 with precipitation rates', 'A basic configuration of the TopoFlow model (v36-3.0.0) aggregating al inputs as a zip file and allowing changing precipitation rates and start/end and time stamp for simulation', 'snowmelt, precipitation, evapotranspiration, infiltration, channel/overland flow, shallow subsurface flow, flow diversions', 'This Topoflow configuration has ISRIC with data for 7 soil layers, and using data from the top 3. The start and end dates must be compatible with the data selected. For example, if the data is from 2017 the start date cannot be 2018" There is a ''CHECK_STABILITY'' flag that you can set in some of the input configuration files (channels_kin_wave and infil_richards_1d). Since there is no way to predict stable time step size in advance, we have calculated it by trial and error to find the largest value that makes the model work. Once this value is set up, the CHECK_STABILITY flag may be switched to ''No'' to speed up the execution of the model. The vertical spacing in the infiltration component (set via dz and nz) layers needs to be small to handle a wide range of rainfall values, but this means the timestep (dt) also needs to be smaller to keep the model stable', 'https://raw.githubusercontent.com/mosoriob/topoflow/master/mint_component.zip', NULL, 'https://w3id.org/okn/i/mint/MOSORIO-TOPOFLOW%253A20.8.27', NULL, NULL, NULL, NULL, NULL, NULL, 'https://w3id.org/okn/i/mint/peckham_scott') ON CONFLICT DO NOTHING;
