INSERT INTO public.modelcatalog_configuration (id, software_version_id, model_configuration_id, label, description, keywords, usage_notes, has_component_location, has_implementation_script_location, has_software_image, has_model_result_table, has_region, calibration_interval, calibration_method, parameter_assignment_method, valid_until, author_id) VALUES ('https://w3id.org/okn/i/mint/724db4ed-27c3-40ea-bf99-5edcb7f80c3c', 'https://w3id.org/okn/i/mint/d6d6b994-db7b-4320-ae5c-7cf22157d3a6', NULL, 'SWAT GRDC Workbench V1.0', 'This is a MINT integrated workbench developed as a container for building alternative SWAT initializations and the calibration of these models for Ethiopia and any other basin for which the Global Runoff Data Centre (GRDC) within Bundesanstalt für Gewässerkunde (German Federal Institute of Hydrology; https://www.bafg.de/) has daily data. The initialization builds weather forcing estimates using the FillMissWX tool to which automatically download all available Global Historical Climatology Network (GHCN) daily weather data filling the required weather records for SWAT with data using neighboring monitors data based on three estimation methods including IDW, IDEW, and closest available station. Calibrations for initialized basins are are performed using for all available GRDC pour point data aligned with the preprocessed GHCN weather data for the GRDC period or record using a evolutionary differential evolution algorithm DEoptim algorithm (Ardia et al., 2007; Mullen et al., 2011). SWAT Outputs are written to NetCDF-CF format files as well as PDF summary graphics for integration with other components of the MINT modeling framework. 
