INSERT INTO public.modelcatalog_configuration (id, software_version_id, model_configuration_id, label, description, keywords, usage_notes, has_component_location, has_implementation_script_location, has_software_image, has_model_result_table, has_region, calibration_interval, calibration_method, parameter_assignment_method, valid_until, author_id) VALUES ('https://w3id.org/okn/i/mint/a4914e5f-b716-4d93-9015-8da23db28076', 'https://w3id.org/okn/i/mint/f1ee461c-e32b-4d03-862a-1a3393310ff3', NULL, 'Elm Fire - Fire Behavior', 'ELMFIRE is a wildland fire spread model designed to simulate the progression of fires by numerically solving hyperbolic partial differential equations using Eulerian level set methods. This approach allows it to track the fire front as a curved surface on a regular grid, integrating the governing equations with a narrow-band formulation. The model calculates fire spread rates, including the direction of maximum spread, and assumes an elliptical fire front, treating each point as an independent elliptical "wavelet." ELMFIRE incorporates various environmental factors such as wind, slope, and fuel characteristics, and can simulate both surface and crown fires. It also includes options for wind fluctuations and processes GIS inputs in GeoTiff format, allowing for the quantification of impacts to assets at risk. ELMFIRE has been widely used for real-time forecasting of wildland fire spread and for retrospective analyses, with its predictive accuracy assessed by comparing modeled fire perimeters against observed data.', 'Wildfire, Fire Behavior, Fire Simulation', NULL, 'https://tapis.tapis.io/v3/apps/ElmFire/0.1.0sha-4048e73', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://w3id.org/okn/i/mint/c8399c59-e353-4263-b2d5-937b34570146') ON CONFLICT DO NOTHING;
