INSERT INTO public.modelcatalog_configuration (id, software_version_id, model_configuration_id, label, description, keywords, usage_notes, has_component_location, has_implementation_script_location, has_software_image, has_model_result_table, has_region, calibration_interval, calibration_method, parameter_assignment_method, valid_until, author_id) VALUES ('https://w3id.org/okn/i/mint/modflow_2005_BartonSprings_avg', NULL, 'https://w3id.org/okn/i/mint/modflow_2005_cfg', 'MODFLOW 2005 model setup calibrated for the Barton Springs region. Files for average conditions have been pre-selected', 'The Barton Springs groundwater model completed in 2001 by Scanlon with others was constructed to match water levels and spring flow from a period of wetter than normal rainfall conditions. An assessment of the model post completion revealed that it overestimates spring flow and underpredicts water-level elevations generally, but it does capture general aquifer behaviors and response.', NULL, NULL, 'https://github.com/mintproject/MINT-WorkflowDomain/raw/master/WINGSWorkflowComponents/MODFLOW2005/MODFLOW2005.zip', 'https://github.com/mintproject/MINT-WorkflowDomain/raw/master/WINGSWorkflowComponents/MODFLOW2005/src/run', 'https://w3id.org/okn/i/mint/MINTPROJECT-MODFLOW-2005%253ALATEST', NULL, 'https://w3id.org/okn/i/mint/Barton_Springs', NULL, NULL, 'Calibration', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_configuration (id, software_version_id, model_configuration_id, label, description, keywords, usage_notes, has_component_location, has_implementation_script_location, has_software_image, has_model_result_table, has_region, calibration_interval, calibration_method, parameter_assignment_method, valid_until, author_id) VALUES ('https://w3id.org/okn/i/mint/modflow_2005_BartonSprings_drought', NULL, 'https://w3id.org/okn/i/mint/modflow_2005_cfg', 'MODFLOW 2005 model setup calibrated for the Barton Springs region on a drought season (files pre-selected)', 'In 2011 the Texas Water Development Board (TWDB) completed the recalibration of The Barton Springs segment of the Edwards (Balcones Fault Zone) Aquifer Groundwater Availability Model; following a request by Groundwater Management Area 10 to evaluate pumping that would result in specified spring flows. Measurements were taken at Barton Springs of 11, 9, 7, 5, 3 cubic-feet per second under drought-of-record conditions.', NULL, NULL, 'https://github.com/mintproject/MINT-WorkflowDomain/raw/master/WINGSWorkflowComponents/MODFLOW2005/MODFLOW2005.zip', 'https://github.com/mintproject/MINT-WorkflowDomain/raw/master/WINGSWorkflowComponents/MODFLOW2005/src/run', 'https://w3id.org/okn/i/mint/MINTPROJECT-MODFLOW-2005%253ALATEST', NULL, 'https://w3id.org/okn/i/mint/Barton_Springs', NULL, NULL, 'Calibration', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_configuration (id, software_version_id, model_configuration_id, label, description, keywords, usage_notes, has_component_location, has_implementation_script_location, has_software_image, has_model_result_table, has_region, calibration_interval, calibration_method, parameter_assignment_method, valid_until, author_id) VALUES ('https://w3id.org/okn/i/mint/modflow_2005_cfg', 'https://w3id.org/okn/i/mint/modflow_2005', NULL, 'MODFLOW 2005 configuration', 'MODFLOW 2005 configuration using variable recharge files', 'groundwater modeling; steady and nonsteady flow; areal recharge; evapotranspiration; flow to drains; flow through river beds', NULL, 'https://github.com/mintproject/MINT-WorkflowDomain/raw/master/WINGSWorkflowComponents/MODFLOW2005/MODFLOW2005.zip', 'https://github.com/mintproject/MINT-WorkflowDomain/raw/master/WINGSWorkflowComponents/MODFLOW2005/src/run', 'https://w3id.org/okn/i/mint/MINTPROJECT-MODFLOW2005%253ALATEST', NULL, NULL, NULL, NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_configuration (id, software_version_id, model_configuration_id, label, description, keywords, usage_notes, has_component_location, has_implementation_script_location, has_software_image, has_model_result_table, has_region, calibration_interval, calibration_method, parameter_assignment_method, valid_until, author_id) VALUES ('https://w3id.org/okn/i/mint/pihm-v2', 'https://w3id.org/okn/i/mint/pihm_2.2', NULL, 'PIHM configuration', 'PIHM configuration for the region of South Sudan', 'channel routing; surface overland flow; subsurface flow; interception; snow melt; evapotranspiration; semi-discrete approach', NULL, 'https://github.com/KnowledgeCaptureAndDiscovery/MINT-WorkflowDomain/raw/master/WINGSWorkflowComponents/pihm/pihm.zip', 'https://github.com/mintproject/MINT-WorkflowDomain/raw/master/WINGSWorkflowComponents/pihm-v2/run', 'https://w3id.org/okn/i/mint/MINTPROJECT-PIHM%253AV2', NULL, NULL, NULL, NULL, NULL, NULL, 'https://w3id.org/okn/i/mint/mayani_rajiv') ON CONFLICT DO NOTHING;
