INSERT INTO public.modelcatalog_dataset_specification (id, label, description, has_format, has_dimensionality, "position") VALUES ('https://w3id.org/okn/i/mint/054957d6-5ded-4507-9807-9645c6dc300d', 'pcp_cli', NULL, 'cli', NULL, '45') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_dataset_specification (id, label, description, has_format, has_dimensionality, "position") VALUES ('https://w3id.org/okn/i/mint/0694b569-faba-4b1d-99b0-31374db43821', 'cycles_weather_soil', 'Cycles zipped weather and soil description files. The weather files typically have a suffix of .weather, but any suffix or file naming convention can be used so long as the name of the weather file listed in the control file exactly matches the name of the weather file to be used in the input directory. Weather files contain three lines at the beginning with the keyword tags LATITUDE, ALTITUDE, and SCREENING_HEIGHT, each followed by a tab-delimited value. Altitude and screening height values should be entered in meters. Screening height is the height of the weather station instruments above the land surface. Following these three lines is a row of tab-delimited column headers in the order YEAR, DOY, PP, TX, TN, SOLAR, RHX, RHN, WIND. Soil files typically have a suffix of .soil, but any naming convention can be used as long as it matches the soil file name listed in the control file. The soil file starts with three lines at the beginning with the keyword tags CURVE_NUMBER, SLOPE, and TOTAL_LAYERS, with each keyword followed by a tab-delimited value.', 'zip', NULL, NULL) ON CONFLICT DO NOTHING;
