INSERT INTO public.modelcatalog_dataset_specification (id, label, description, has_format, has_dimensionality, "position") VALUES ('https://w3id.org/okn/i/mint/cycles-0.10.2-alpha-collection-oromia-single-point_weather_soil', 'cycles_weather_soil', 'Cycles zipped weather and soil description files. The weather files typically have a suffix of .weather, but any suffix or file naming convention can be used so long as the name of the weather file listed in the control file exactly matches the name of the weather file to be used in the input directory. Weather files contain three lines at the beginning with the keyword tags LATITUDE, ALTITUDE, and SCREENING_HEIGHT, each followed by a tab-delimited value. Altitude and screening height values should be entered in meters. Screening height is the height of the weather station instruments above the land surface. Following these three lines is a row of tab-delimited column headers in the order YEAR, DOY, PP, TX, TN, SOLAR, RHX, RHN, WIND. Soil files typically have a suffix of .soil, but any naming convention can be used as long as it matches the soil file name listed in the control file. The soil file starts with three lines at the beginning with the keyword tags CURVE_NUMBER, SLOPE, and TOTAL_LAYERS, with each keyword followed by a tab-delimited value.', 'zip', NULL, '1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_dataset_specification (id, label, description, has_format, has_dimensionality, "position") VALUES ('https://w3id.org/okn/i/mint/cycles-0.10.2-alpha-collection-oromia_soilProfile', 'cycles_soilProfile', 'Results in this file are for the sum of all layers in the soil profile, including surface residues', 'dat', NULL, '1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_dataset_specification (id, label, description, has_format, has_dimensionality, "position") VALUES ('https://w3id.org/okn/i/mint/cycles-0.10.2-alpha-collection-oromia_somF', 'cycles_som', 'Cycles annual SOM file. This file provides annualized measurements of the carbon concentration and saturation ratio by soil layer. One column will be created for each layer in the soil profile for the variables where the column heading indicates LAYER 1..x', 'dat', NULL, '2') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_dataset_specification (id, label, description, has_format, has_dimensionality, "position") VALUES ('https://w3id.org/okn/i/mint/cycles-0.10.2-alpha-collection-oromia_summary', 'cycles_summary', 'The summary file provides a summarized output of total C inputs over the duration of the simulation and average annual rates for N cycling processes.', 'dat', NULL, '6') ON CONFLICT DO NOTHING;
