INSERT INTO public.modelcatalog_software (id, label, description, keywords, license, website, date_created, date_published, has_documentation, has_download_url, has_purpose, author_id, type) VALUES ('https://w3id.org/okn/i/mint/ClimComp', 'ClimComp', 'ClimComp is a Python routine for comparing the seasonal prediction with the average climatology', 'seasonal climate;climate; climatology;comparison', NULL, 'https://github.com/KnowledgeCaptureAndDiscovery/ClimComp', '2018', NULL, 'https://github.com/KnowledgeCaptureAndDiscovery/ClimComp/blob/master/README.md', 'https://github.com/KnowledgeCaptureAndDiscovery/ClimComp', NULL, 'https://w3id.org/okn/i/mint/khider_deborah', 'https://w3id.org/okn/o/sdm#EmpiricalModel') ON CONFLICT DO NOTHING;
