INSERT INTO public.modelcatalog_software (id, label, description, keywords, license, website, date_created, date_published, has_documentation, has_download_url, has_purpose, author_id, type) VALUES ('https://w3id.org/okn/i/mint/d83f0bf5-dceb-4f0c-82dc-2dfcfa2619e8', 'Smoke detection machine learning model', 'Convolutional neural network model for smoke detection', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://w3id.org/okn/o/sdm#Model') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_software (id, label, description, keywords, license, website, date_created, date_published, has_documentation, has_download_url, has_purpose, author_id, type) VALUES ('https://w3id.org/okn/i/mint/DSI', 'Drought Indices Model', 'The Drought Indices Model (SDI) uses data from several climate sources (CHIRPS, GLDAS, FLDAS, and ECMWF) to generate three useful climate indices: the Standardized Precipitation Index, Standardized Precipitation Evapotranspiration Index, and the Potential Evapotranspiration.', 'Climate; drought; index', 'https://github.com/mintproject/droughtIndices/blob/master/README.md', NULL, '2019', '2019', 'https://github.com/mintproject/droughtIndices/blob/master/README.md', 'https://github.com/mintproject/droughtIndices', 'drought indices calculation', 'https://w3id.org/okn/i/mint/khider_deborah', 'https://w3id.org/okn/o/sdm#Model') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_software (id, label, description, keywords, license, website, date_created, date_published, has_documentation, has_download_url, has_purpose, author_id, type) VALUES ('https://w3id.org/okn/i/mint/DSSAT', 'Decision Support System for Agrotechnology Transfer (DSSAT)', 'Decision Support System for Agrotechnology Transfer (DSSAT) is software application program that comprises dynamic crop growth simulation models for over 40 crops. DSSAT is supported by a range of utilities and applications for weather, soil, genetic, crop management and observational experimental data. Includes example data sets for all crop models. The crop simulation models simulate growth, development and yield as a function of the soil-plant-atmosphere dynamics (https://dssat.net/. 2019)', 'Decision Support System; Agrotechnology; crop growth simulation; weather; soil; genetic; crop management;soil-plant-atmosphere dynamics', NULL, 'https://dssat.net/', '1989', NULL, 'https://dssat.net', 'https://apps.agapps.org/ide/serial/index.php/request?sft=3', NULL, 'https://w3id.org/okn/i/mint/hoogenboom_gerrit', 'https://w3id.org/okn/o/sdm#Theory-GuidedModel') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_software (id, label, description, keywords, license, website, date_created, date_published, has_documentation, has_download_url, has_purpose, author_id, type) VALUES ('https://w3id.org/okn/i/mint/ecff9a6d-3d30-4b47-8230-d31cf6d6dd3c', 'Whisper (OpenAI Whisper Automatic Speech Recognition)', 'Whisper is a state-of-the-art model for automatic speech recognition (ASR) and speech translation, proposed in the paper Robust Speech Recognition via Large-Scale Weak Supervision by Alec Radford et al. from OpenAI. Trained on >5M hours of labeled data, Whisper demonstrates a strong ability to generalise to many datasets and domains in a zero-shot setting. The Whisper architecture is a simple end-to-end approach, implemented as an encoder-decoder Transformer. Input audio is split into 30-second chunks, converted into a log-Mel spectrogram, and then passed into an encoder. A decoder is trained to predict the corresponding text caption, intermixed with special tokens that direct the single model to perform tasks such as language identification, phrase-level timestamps, multilingual speech recognition, and speech translation. The model shows improved robustness to accents, background noise, and technical language compared to previous approaches.
INSERT INTO public.modelcatalog_software (id, label, description, keywords, license, website, date_created, date_published, has_documentation, has_download_url, has_purpose, author_id, type) VALUES ('https://w3id.org/okn/i/mint/ECONOMIC_AGGREGATE_CROP_SUPPLY', 'Economic aggregate crop supply response model (EACS)', 'The Aggregate crop supply response model (EACS) describes an aggregate crop supply response model for a region (tested for South Sudan). This is a regional-scale aggregate model of agricultural supply for a specified set of crops (cassava, groundnuts, maize, sesame seed, and sorghum).', 'economy; land use; crop production; fertilizer costs', NULL, NULL, '2018', NULL, NULL, NULL, 'optimal fertilizing rates; estimated yield', 'https://w3id.org/okn/i/mint/cobourn_kelly', 'https://w3id.org/okn/o/sdm#Theory-GuidedModel') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_software (id, label, description, keywords, license, website, date_created, date_published, has_documentation, has_download_url, has_purpose, author_id, type) VALUES ('https://w3id.org/okn/i/mint/FSI', 'Flood Severity Index model', 'This Python model calculates a flood severity index based on the annual maxima of volumetric flow for the period 1981-2017 obtained from the GloFAS data (http://www.globalfloods.eu/). The thresholds were estimated from a Gumbel distribution using the methods of L-moments. The severity is based on a 2-yr return period (medium), 5-yr return period (high), and 20-yr return period (severe).', 'hydrology; flood; index', 'https://github.com/mintproject/FloodSeverityIndex/blob/master/LICENSE', NULL, '2019', '2019', 'https://github.com/mintproject/FloodSeverityIndex/blob/master/README.md', 'https://github.com/mintproject/FloodSeverityIndex', 'flood severity index calculation', 'https://w3id.org/okn/i/mint/khider_deborah', 'https://w3id.org/okn/o/sdm#EmpiricalModel') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_software (id, label, description, keywords, license, website, date_created, date_published, has_documentation, has_download_url, has_purpose, author_id, type) VALUES ('https://w3id.org/okn/i/mint/HAND', 'Height Above Nearest Drainage (HAND)', 'The Height Above the Nearest Drainage (HAND) is a model that normalizes topography according to the local relative heights found along a given drainage network. Model output shows a high correlation with the depth of the water table in a region and provide an accurate spatial representation of soil water environments. HAND takes as input a Digital Elevation Map of a given region, producing as output a normalized draining potential (or relative vertical flowpath-distance) to the nearest drainages.', 'Relative height;Normalization of topography;Gravitational potential;Draining potential;Flow path;Drainage network', NULL, NULL, '2010', NULL, 'http://hydrology.usu.edu/taudem/taudem5/documentation.html', 'https://github.com/dtarb/TauDEM', 'Flooding map generation', 'https://w3id.org/okn/i/mint/taborton_david', 'https://w3id.org/okn/o/sdm#EmpiricalModel') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_software (id, label, description, keywords, license, website, date_created, date_published, has_documentation, has_download_url, has_purpose, author_id, type) VALUES ('https://w3id.org/okn/i/mint/MODFLOW', 'MODFLOW', 'Modflow is a popular open-source groundwater flow model distributed by the U.S. Geological survey', 'groundwater modeling; steady and nonsteady flow; areal recharge; evapotranspiration; flow to drains; flow through river beds', 'https://creativecommons.org/publicdomain/zero/1.0/', 'https://www.usgs.gov/mission-areas/water-resources/science/modflow-and-related-programs', '1983', NULL, 'https://water.usgs.gov/ogw/modflow/', 'https://www.usgs.gov/software/modflow-2005-usgs-three-dimensional-finite-difference-ground-water-model', 'water budget estimation; total pumping bugdets', NULL, 'https://w3id.org/okn/o/sdm#Theory-GuidedModel') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_software (id, label, description, keywords, license, website, date_created, date_published, has_documentation, has_download_url, has_purpose, author_id, type) VALUES ('https://w3id.org/okn/i/mint/PIHM', 'Penn State Integrated Hydrology Model (PIHM)', 'The Penn State Integrated Hydrologic Modeling System (PIHM) is a finite volume code used for simulating the distributed hydrologic states of a given watershed or river basin. PIHM accounts for many physical processes including: land surface processes (evaporation- transpiration, canopy interception,  snowmelt) overland/channel flow coupled to groundwater flow. PIHM can include reservoirs and flow control structures. PIHM applies adaptive time stepping and uses the method of lines to solve the system of implicit equations.', 'channel routing; surface overland flow; subsurface flow; interception; snow melt; evapotranspiration; semi-discrete approach', 'https://creativecommons.org/publicdomain/zero/1.0/', 'http://www.pihm.psu.edu/index.html', '2007', NULL, 'http://www.pihm.psu.edu', 'http://www.pihm.psu.edu/pihmgis_downloads.html', 'surface water modeling; flooding prediction', 'https://w3id.org/okn/i/mint/duffy_christopher', 'https://w3id.org/okn/o/sdm#Theory-GuidedModel') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_software (id, label, description, keywords, license, website, date_created, date_published, has_documentation, has_download_url, has_purpose, author_id, type) VALUES ('https://w3id.org/okn/i/mint/SWAT', 'The Soil & Water Assessment Tool (SWAT)', 'The Soil & Water Assessment Tool (SWAT) is a small watershed to river basin-scale model used to simulate the quality and quantity of surface and ground water and predict the environmental impact of land use; land management practices and climate change (https://swat.tamu.edu/ 2019)', 'Soil; watershed;surface water; ground water;environmental impacts; land use; land management; climate change;soil erosion; source pollution', NULL, 'https://swat.tamu.edu/', '1993', NULL, 'https://swat.tamu.edu/docs/', 'https://plus.swat.tamu.edu/downloads/swatplustools-installer-1.2.0.zip', NULL, 'https://w3id.org/okn/i/mint/engel_bernard', 'https://w3id.org/okn/o/sdm#Theory-GuidedModel') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_software (id, label, description, keywords, license, website, date_created, date_published, has_documentation, has_download_url, has_purpose, author_id, type) VALUES ('https://w3id.org/okn/i/mint/TOPOFLOW', 'TopoFlow', 'Topoflow is a powerful spatially-distributed hydrologic model for various physical processes in a watershed, with the goal of accurately predicting how various hydrologic variables will evolve in time in response to climatic forcings.', 'snowmelt;precipitation;evapotranspiration;infiltration;channel/overland flow;shallow subsurface flow;flow diversions', NULL, 'https://csdms.colorado.edu/wiki/Model:TopoFlow', NULL, NULL, 'https://github.com/peckhams/topoflow/blob/master/docs/', 'https://csdms.colorado.edu/pub/models/doi-source-code/topoflow-10.1594.IEDA.100174-3.1.0.tar.gz', NULL, 'https://w3id.org/okn/i/mint/peckham_scott', 'https://w3id.org/okn/o/sdm#Theory-GuidedModel') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_software (id, label, description, keywords, license, website, date_created, date_published, has_documentation, has_download_url, has_purpose, author_id, type) VALUES ('https://w3id.org/okn/i/mint/WGEN', 'WGEN', 'WGEN: A global weather generator for daily data derived from the Global Weather Generator (GWGEN)', 'weather generator; climatology; meteorology; global meteorological database; temperature; precipitation; cloud cover; windspeed', NULL, NULL, '2017', '2017', 'https://arve-research.github.io/gwgen/', 'https://github.com/ARVE-Research/gwgen/releases', NULL, 'https://w3id.org/okn/i/mint/somer_philipp', 'https://w3id.org/okn/o/sdm#EmpiricalModel') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_software (id, label, description, keywords, license, website, date_created, date_published, has_documentation, has_download_url, has_purpose, author_id, type) VALUES ('https://w3id.org/okn/i/mint/wmobley-insar-deformation-processing-workflow', 'InSAR Deformation Processing Workflow', 'Workflow for converting repeat-pass SAR imagery into ground deformation products for subsidence monitoring and model calibration.', 'InSAR; SAR; subsidence; deformation; remote sensing; Sentinel-1; campaign-scale', 'https://github.com/insarlab/MintPy', 'https://doi.org/10.1016/j.cageo.2019.104331', NULL, NULL, 'https://doi.org/10.1016/j.cageo.2019.104331; https://doi.org/10.1029/2011EO280002; https://github.com/insarlab/MintPy; https://topex.ucsd.edu/gmtsar/; https://gmtsar.github.io/documentation/', NULL, 'observational_constraint', NULL, 'https://w3id.org/okn/o/sd#Software') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_software (id, label, description, keywords, license, website, date_created, date_published, has_documentation, has_download_url, has_purpose, author_id, type) VALUES ('https://w3id.org/okn/i/mint/wmobley-parflow', 'ParFlow', 'Parallel integrated hydrologic model simulating variably saturated flow, overland flow, and groundwater-surface water interactions.', 'ParFlow; HPC; recharge; watershed', 'https://github.com/parflow/parflow/blob/master/LICENSE.txt', 'https://doi.org/10.5194/gmd-13-1373-2020', NULL, NULL, 'https://doi.org/10.5194/gmd-13-1373-2020; https://doi.org/10.1016/j.advwatres.2005.08.006; https://www.parflow.org/; https://github.com/parflow/parflow/tree/master/test; https://parflow.readthedocs.io/; https://github.com/parflow/parflow/blob/master/LICENSE.txt', NULL, 'process_model', NULL, 'https://w3id.org/okn/o/sd#Software') ON CONFLICT DO NOTHING;
