INSERT INTO public.modelcatalog_software_version (id, software_id, version_id, label, description, keywords, has_usage_notes, date_created, has_source_code, short_description, limitations, parameterization, runtime_estimation, theoretical_basis, author_id) VALUES ('https://w3id.org/okn/i/mint/584a9c88-e26c-4721-a0a2-d3f38519c023', 'https://w3id.org/okn/i/mint/9884264e-c2f7-4efd-9138-6678d7cb3899', 'v0.0.3a2', 'PyGeoflood', 'GeoFlood is a high-resolution, terrain-based flood inundation mapping tool designed for rapid, large-scale flood prediction and emergency response. It leverages LiDAR-derived digital elevation models and combines the Height Above Nearest Drainage (HAND) method with an enhanced version of GeoNet for accurate channel network extraction. GeoFlood generates synthetic rating curves and flood extents using simplified hydraulic assumptions, enabling efficient mapping in both rural and urban watersheds. Its streamlined workflow is computationally efficient and ideal for real-time applications, supporting decision-making during extreme weather events and flood disasters.
