INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_base_temperature_for_development', 'BASE_TEMPERATURE_FOR_DEVELOPMENT', 'he base temperature (degree C) for phenological development and accumulation of thermal time. Air temperatures below this value will not add to cumulative thermal time. Air temperatures above this value and below OPTIMUM_TEMPERATURE_FOR_DEVELOPMENT will accumulate thermal time according to air temperature â€“ BASE_TEMPERATURE_FOR_DEVELOPMENT.', NULL, 'BASE_TEMPERATURE_FOR_DEVELOPMENT', NULL, 'https://w3id.org/okn/i/mint/degCTe') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_bd', 'BD', 'Soil mass dry and wihtout rock divided by the sampled volume', 'bulk density', 'BD', 'https://w3id.org/okn/i/mint/SOIL~NO-ROCK~DRY__MASS-PER-VOLUME_DENSITY', 'https://w3id.org/okn/i/mint/Mg+m-3') ON CONFLICT DO NOTHING;
