INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_c3', 'C3', 'Whether the crop has a C3 photosynthetic pathway (value = 1) or a C4 pathway (value = 0).', NULL, 'C3', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_c_diff', 'C DIFF', 'The change in the stabilized soil C pool size between the beginning and end of the year.', NULL, 'C DIFF', 'https://w3id.org/okn/i/mint/SOIL_CARBON_POOL~STABILIZED_CARBON__ONE-YEAR_CHANGE_OF_MASS', 'https://w3id.org/okn/i/mint/Mg%2Fyear') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_clay', 'CLAY', 'clay particle size fraction size fraction of each soil layer in %.', 'clay percentage', 'CLAY', 'https://w3id.org/okn/i/mint/SOIL_CLAY_PARTICLE__VOLUME_FRACTION', 'https://w3id.org/okn/i/mint/%25') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_clipping_biomass_threshold_lower', 'CLIPPING_BIOMASS_THRESHOLD_LOWER', 'The aboveground plant biomass threshold (in Mg/ha), which remains un-harvestable during clipping events. This value represents the mass of living plant biomass that would remain in the field after a clipping event with a RESIDUE_REMOVED value of 100.', NULL, 'CLIPPING_BIOMASS_THRESHOLD_LOWER', NULL, 'https://w3id.org/okn/i/mint/Mg+ha-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_clipping_biomass_threshold_upper', 'CLIPPING_BIOMASS_THRESHOLD_UPPER', 'The aboveground plant biomass threshold (in Mg/ha) that will trigger a clipping event or forage harvest.', NULL, 'CLIPPING_BIOMASS_THRESHOLD_UPPER', NULL, 'https://w3id.org/okn/i/mint/Mg+ha-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_cn', 'CURVE_NUMBER', 'A number that describes the soil disposition towards runoff (100 = all runoff) NRCS method adapted to field models', 'soil curve number', 'CURVE_NUMBER', 'https://w3id.org/okn/i/mint/LAND_SURFACE_WATER__USDANRCS_RUNOFF_CURVE_NUMBER', NULL) ON CONFLICT DO NOTHING;
