INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_crop_name', 'CROP_NAME', 'Name of the crop used in the simulation', 'crop name', 'CROP_NAME', 'https://w3id.org/okn/i/mint/CROP__NAME', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_crop_v', 'CROP', 'The crop name.', NULL, 'CROP', 'https://w3id.org/okn/i/mint/CROP__NAME', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_c_sat._ratio', 'STAND. RESID. C:N', 'The C:N ratio of standing residue on the soil surface.', NULL, 'STAND. RESID. C:N', 'https://w3id.org/okn/i/mint/SOIL_SURFACE_RESIDUE~STANDING_CARBON-TO-NITROGEN__MASS_RATIO', 'https://w3id.org/okn/i/mint/Cs+Cx-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_cum._biomass', 'CUM. BIOMASS', 'The cumulative total crop biomass; sum of aboveground and roots.', NULL, 'CUM. BIOMASS', 'https://w3id.org/okn/i/mint/CROP_BIOMASS__MASS-PER-AREA_DENSITY', 'https://w3id.org/okn/i/mint/Mg+ha-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_cum._n_stress', 'CUM. N STRESS', 'Cumulative N stress over the duration of crop growth; calculated as the sum of each daily N stress weighted by the daily fraction of thermal time accumulated to maturity.', NULL, 'CUM. N STRESS', 'https://w3id.org/okn/i/mint/CROP_NITROGEN__THERMAL-TIME-TO-MATURITY_WEIGHTED_STRESS_FRACTION', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_date', 'DATE', 'Calendar date in the simulation.', NULL, 'DATE', NULL, 'https://w3id.org/okn/i/mint/date') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_doy', 'DOY', 'Calendar day from 1 to 366', 'day of the year', 'DOY', 'https://w3id.org/okn/i/mint/CROP__PLANTING_START_TIME', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_drainage', 'DRAINAGE', 'Water drainage from the bottom of the soil profile.', NULL, 'DRAINAGE', 'https://w3id.org/okn/i/mint/SOIL_PROFILE_BOTTOM_WATER__DRAINAGE_VOLUME_FLUX', 'https://w3id.org/okn/i/mint/mm+day-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_dz', 'DZ', 'Soil layer thickness', 'soil layer thickness', 'DZ', 'https://w3id.org/okn/i/mint/SOIL_LAYER__THICKNESS', 'https://w3id.org/okn/i/mint/mL') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_end_doy', 'END_DOY', 'The last numerical day of the year (0 to 365 or 366) on which the planting operation is to be performed when conditional planting is activated.', 'end day of the year', 'END_DOY', 'https://w3id.org/okn/i/mint/MODEL__SIMULATION_END_TIME', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_end_year', 'SIMULATION_END_YEAR', 'The year to start the simulation. All simulations start on January 1 of the given year. There must be records in the weather file starting from January 1 of this year', 'simulation end year', 'SIMULATION_END_YEAR', 'https://w3id.org/okn/i/mint/MODEL__SIMULATION_END_TIME', 'https://w3id.org/okn/i/mint/yearT') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_final_c', 'FINAL C', 'The pool size of stabilized soil C at the end of the year.', NULL, 'FINAL C', 'https://w3id.org/okn/i/mint/SOIL_CARBON_POOL~STABILIZED_CARBON__YEAR-END_MASS', 'https://w3id.org/okn/i/mint/Mg%2Fyear') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_final_partitioning_to_shoot', 'FINAL_PARTITIONING_TO_SHOOT', 'The fraction of growth partitioned to aboveground biomass (as opposed to roots) at the end of crop phenological development (physiological maturity). Values can range from 0 to 1. Perennials have lower values than annuals.', NULL, 'FINAL_PARTITIONING_TO_SHOOT', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_final_prof_c', 'FINAL PROF C', 'The C content in the stabilized soil C pool at the end of the simulation.', NULL, 'FINAL PROF C', 'https://w3id.org/okn/i/mint/SOIL_CARBON_POOL~STABILIZED_CARBON__FINAL_MASS', 'https://w3id.org/okn/i/mint/MgM') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_flowering_tt', 'FLOWERING_TT', 'The thermal time to flowering, in growing degree C days, calculated using the base, optimum, and maximum temperatures for development listed in BASE_TEMPERATURE_FOR_DEVELOPMENT, OPTIMUM_TEMPERATURE_FOR_DEVELOPEMENT, and MAX_TEMPERATURE_FOR_DEVELOPMENT.', NULL, 'FLOWERING_TT', NULL, 'https://w3id.org/okn/i/mint/degC%2Fday') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_forage_n', 'FORAGE N', 'Forage or removed residue N content at harvest.', NULL, 'FORAGE N', 'https://w3id.org/okn/i/mint/FORAGE-OR-RESIDUE~REMOVED_NITROGEN_AT-HARVEST__MASS-PER-AREA_YIELD', 'https://w3id.org/okn/i/mint/Mg+ha-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_forage_yield', 'FORAGE YIELD', 'Forage yield or removed residue biomass at harvest.', NULL, 'FORAGE YIELD', 'https://w3id.org/okn/i/mint/FORAGE-OR-RESIDUE~REMOVED_AT-HARVEST__MASS-PER-AREA_YIELD', 'https://w3id.org/okn/i/mint/Mg+ha-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_frac_intercep', 'FRAC INTERCEP', 'The fraction of solar radiation intercepted by the crop canopy.', NULL, 'FRAC INTERCEP', 'https://w3id.org/okn/i/mint/CROP_CANOPY_RADIATION~SOLAR__INTERCEPTION_ENERGY_FLUX_FRACTION', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_fraction', 'FRACTION', 'The planting density (0 to 1), where 1 is a monoculture planting rate and < 1 indicates a proportionally reduced seeding rate. This feature allows for the planting of multiple species in a plant community at different initial densities.', 'fraction', 'FRACTION', 'https://w3id.org/okn/i/mint/CROP__PLANTING_COUNT-PER-AREA_DENSITY_FRACTION', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_grain_n', 'GRAIN N', 'Grain N content at harvest.', NULL, 'GRAIN N', 'https://w3id.org/okn/i/mint/GRAIN_NITROGEN_AT-HARVEST__MASS-PER-AREA_DENSITY', 'https://w3id.org/okn/i/mint/Mg+ha-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_grain_yield', 'GRAIN YIELD', 'Grain yield removed from the field dry basis', 'grain yield', 'GRAIN YIELD', 'https://w3id.org/okn/i/mint/GRAIN~DRY__MASS-PER-AREA_YIELD', 'https://w3id.org/okn/i/mint/Mg+ha-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_harvest_biomass_destiny', 'CLIPPING_BIOMASS_DESTINY', 'This value controls the destiny of biomass cut by clipping events, with options of REMOVE, RETURN, or GRAZING. REMOVE will treat the clipped biomass as a harvested crop. RETURN will treat the clipped biomass as a residue returned to the soil surface, with the allocation to standing versus flattened residue pools controlled by the STANDING_RESIDUE_AT_HARVEST value. GRAZING will treat the clipped biomass as being consumed by livestock, with 50% of the carbon in clipped biomass returned to the soil surface manure C pool and 50% of the carbon respired by livestock as CO2, and with 50% of the nitrogen in clipped biomass returned to the soil surface in the manure N pool and 50% of the nitrogen returned as urine to the NH4+ pool of the first soil layer.', NULL, 'CLIPPING_BIOMASS_DESTINY', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_harvest_index', 'HARVEST INDEX', 'Fraction of aboveground biomass harvested as grain.', NULL, 'HARVEST INDEX', 'https://w3id.org/okn/i/mint/GROUND~ABOVE_BIOMASS~HARVESTED_GRAIN__MASS_FRACTION', 'https://w3id.org/okn/i/mint/Mg+Mg-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_harvest_timing', 'HARVEST_TIMING', 'The percent of thermal time to crop maturity that will trigger a clipping event or grain harvest. As an example, if HARVEST_TIMING is set to 90, and the MATURITY_TT is 1000, the crop will be clipped when the cumulative thermal time of crop development reaches 900 growing degree days. If the harvest timing is less than 100, the crop will be clipped as a forage and will continue to regrow. If the harvest timing is greater than 100, the crop will have reached physiological maturity and will be harvested as a grain crop and killed after harvested. A value of -999 can be entered to trigger a default value of 101, which will result in the crop being harvested for grain on the first day after it reaches physiological maturity.', NULL, 'HARVEST_TIMING', NULL, 'https://w3id.org/okn/i/mint/%25') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_hn', 'RHn', 'relative humidity minimum', 'relative humidity minimum', 'RHn', 'https://w3id.org/okn/i/mint/ATMOSPHERE_AIR_WATER~VAPOR__MIN_OF_RELATIVE_SATURATION', 'https://w3id.org/okn/i/mint/%25') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_humified_c', 'HUMIFIED C', 'The total quantity of decomposed C added to microbial and soil C pools over the duration of the simulation.', NULL, 'HUMIFIED C', 'https://w3id.org/okn/i/mint/SOIL_POOL-AND-POOL~MICROBIAL_CARBON~DECOMPOSED__ADDITION_MASS', 'https://w3id.org/okn/i/mint/MgM') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_humified_c2', 'HUMIFIED C', 'Quantity of decomposed C added to microbial and stabilized C pools.', NULL, 'HUMIFIED C', 'https://w3id.org/okn/i/mint/SOIL_CARBON_POOL~MICROBIAL-AND-STABILIZED_CARBON~DECOMPOSED__MASS_ADDITION_RATE', 'https://w3id.org/okn/i/mint/Mg%2Fyear') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_hx', 'RHx', 'relative humidity maximum', 'relative humidity maximum', 'RHx', 'https://w3id.org/okn/i/mint/ATMOSPHERE_AIR_WATER~VAPOR__MAX_OF_RELATIVE_SATURATION', 'https://w3id.org/okn/i/mint/Pa+Pa-1+x-100') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_immobilization', 'IMMOBILIZATION', 'Gross N immobilization in microbial biomass or stabilized soil organic N pools.', NULL, 'IMMOBILIZATION', 'https://w3id.org/okn/i/mint/BIOMASS~MICROBIAL-OR-SOIL_POOL~ORGANIC~STABILIZED_NITROGEN__GROSS_MASS-PER-AREA_IMMOBILIZATION_DENSITY', 'https://w3id.org/okn/i/mint/kg+ha-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_infiltration', 'INFILTRATION', 'Net infiltration into soil', NULL, 'INFILTRATION', 'https://w3id.org/okn/i/mint/SOIL_WATER__INFILTRATION_VOLUME_FLUX', 'https://w3id.org/okn/i/mint/m+day-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_init_c_mass', 'INIT C MASS', 'The pool size of stabilized soil C at the beginning of the year.', NULL, 'INIT C MASS', 'https://w3id.org/okn/i/mint/SOIL_CARBON_POOL~STABILIZED_CARBON__YEAR-START_MASS', 'https://w3id.org/okn/i/mint/Mg%2Fyear') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_initial_partitioning_to_shoot', 'INITIAL_PARTITIONING_TO_SHOOT', 'The fraction of growth partitioned to aboveground biomass (as opposed to roots) at the beginning of crop phenological development (seedling emergence). Values can range from 0 to 1. Perennials have lower values than annuals.', NULL, 'INITIAL_PARTITIONING_TO_SHOOT', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_init_prof_c', 'INIT PROF C', 'The C content in the stabilized soil C pool at the beginning of the simulation.', NULL, 'INIT PROF C', 'https://w3id.org/okn/i/mint/SOIL_CARBON_POOL~STABILIZED_CARBON__INITIAL_MASS', 'https://w3id.org/okn/i/mint/MgM') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_irrigation', 'IRRIGATION', 'Water added as irrigation.', NULL, 'IRRIGATION', 'https://w3id.org/okn/i/mint/SOIL_SURFACE_WATER__IRRIGATION_VOLUME_FLUX', 'https://w3id.org/okn/i/mint/mm+day-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_kc', 'KC', 'The crop transpiration coefficient, used to convert reference evapotranspiration based on environmental conditions into crop transpiration.', NULL, 'KC', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_layer', 'LAYER', 'Soil layer number from 1 to an integer that is user defined (or database defined)', 'soil layer number', 'LAYER', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_legume', 'LEGUME', 'Whether the crop is a legume (value = 1) or a non-legume (value = 0).', NULL, 'LEGUME', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_lwp_stress_onset', 'LWP_STRESS_ONSET', 'The leaf water potential (J/kg) threshold for the onset of stress, below which stomatal closure begins, reducing transpiration rates.', NULL, 'LWP_STRESS_ONSET', NULL, 'https://w3id.org/okn/i/mint/J%2Fkg') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_lwp_wilting_point', 'LWP_WILTING_POINT', 'The leaf water potential (J/kg) at wilting point, where transpiration stops.', NULL, 'LWP_WILTING_POINT', NULL, 'https://w3id.org/okn/i/mint/J%2Fkg') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_mass', 'MASS', 'The total mass of the input in kg/ha.', 'mass', 'MASS', 'https://w3id.org/okn/i/mint/LAND_FERTILIZER__APPLIED_MASS', 'https://w3id.org/okn/i/mint/kg+ha-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_maturity_tt', 'MATURITY_TT', 'The thermal time to maturity in growing degree C days.', NULL, 'MATURITY_TT', NULL, 'https://w3id.org/okn/i/mint/degC%2Fday') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_maximum_harvest_index', 'MAXIMUM_HARVEST_INDEX', 'The maximum harvest index possible (Hx), used in the calculation of actual harvest index described below. It is an asymptotic value that can be much higher than the actual maximum HI observed (e.g., 0.8 for corn). Use default values if needed.', NULL, 'MAXIMUM_HARVEST_INDEX', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_maximum_rooting_depth', 'MAXIMUM_ROOTING_DEPTH', 'The maximum depth to which crop roots can grow in meters.', NULL, 'MAXIMUM_ROOTING_DEPTH', NULL, 'https://w3id.org/okn/i/mint/mL') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_maximum_soil_coverage', 'MAXIMUM_SOIL_COVERAGE', 'The maximum crop cover in % is a proxy for light interception potential given by row spacing and other features. This value can be set to less than 100% if the crop canopy does not have the potential to provide full cover, or if the crop is planted with a row spacing such that there will be bare ground present between crop rows (e.g., horticultural production or dry areas).', NULL, 'MAXIMUM_SOIL_COVERAGE', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_max_temperature_for_development', 'MAX_TEMPERATURE_FOR_DEVELOPMENT', 'Air temperatures above this value (degree C) will not add to cumulative thermal time.', NULL, 'MAX_TEMPERATURE_FOR_DEVELOPMENT', NULL, 'https://w3id.org/okn/i/mint/degCTe') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_max_tmp', 'MAX TMP', 'Maximum temperature.', NULL, 'MAX TMP', 'https://w3id.org/okn/i/mint/ATMOSPHERE_BOTTOM_AIR__MAX_OF_TEMPERATURE', 'https://w3id.org/okn/i/mint/degCTe') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_mineralization', 'MINERALIZATION', 'Gross N mineralization from all decomposing organic substrates.', NULL, 'MINERALIZATION', 'https://w3id.org/okn/i/mint/SUBSTRATES~ORGANIC_NITROGEN__GROSS_DECOMPOSITION_MASS-PER-AREA_MINERALIZATION_DENSITY', 'https://w3id.org/okn/i/mint/kg+ha-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_minimum_harvest_index', 'MINIMUM_HARVEST_INDEX', 'The minimum harvest index possible (Hn), used in the calculation of actual harvest index described below. It has some semblance to the fraction of water soluble carbohydrates at flowering or in the first week after flowering in grain crops. Values range from 0 to 0.3.', NULL, 'MINIMUM_HARVEST_INDEX', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_min_temperature_for_cold_damage', 'MIN_TEMPERATURE_FOR_COLD_DAMAGE', 'The minimum temperature (degree C) used in the calculation of the cold damage factor described below. If the daily minimum temperature is below this value, the cold damage factor is set to 0.99.', NULL, 'MIN_TEMPERATURE_FOR_COLD_DAMAGE', NULL, 'https://w3id.org/okn/i/mint/degCTe') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_min_temperature_for_transpiration', 'MIN_TEMPERATURE_FOR_TRANSPIRATION', 'The air temperature (daily average, degree C) below which transpiration by the plant virtually ceases (transpiration is 1% of potential transpiration). This value can constrain crop growth at low temperatures because crop growth is calculated as the minimum of Transpiration Use Efficiency * Transpiration or Radiation Use Efficiency * Radiation Interception. Therefore, if transpiration does not occur, plant biomass accrual does not occur.', NULL, 'MIN_TEMPERATURE_FOR_TRANSPIRATION', NULL, 'https://w3id.org/okn/i/mint/degCTe') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_min_tmp', 'MIN TMP', 'Minimum temperature.', NULL, 'MIN TMP', 'https://w3id.org/okn/i/mint/ATMOSPHERE_BOTTOM_AIR__MIN_OF_TEMPERATURE', 'https://w3id.org/okn/i/mint/degCTe') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_n2o_from_denit', 'N2O FROM DENIT', 'Nitrous oxide emissions from denitrification.', NULL, 'N2O FROM DENIT', 'https://w3id.org/okn/i/mint/SOIL_NITROUS-OXIDE-AS-NITROGEN__DENITRIFICATION_MASS-PER-AREA_EMISSION_DENSITY', 'https://w3id.org/okn/i/mint/kg+ha-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_n2o_from_nitrif', 'N2O FROM NITRIF', 'Nitrous oxide emissions from nitrification.', NULL, 'N2O FROM NITRIF', 'https://w3id.org/okn/i/mint/SOIL_NITROUS-OXIDE-AS-NITROGEN__NITRIFICATION_MASS-PER-AREA_EMISSION_DENSITY', 'https://w3id.org/okn/i/mint/kg+ha-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_n_added', 'N ADDED', 'Cumulative N added to crop biomass to sustain growth in autofertilize mode.', NULL, 'N ADDED', 'https://w3id.org/okn/i/mint/CROP_BIOMASS_NITROGEN__MASS-PER-AREA_APPLICATION_DENSITY', 'https://w3id.org/okn/i/mint/kg+ha-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_name', 'NAME', 'The name of the crop. This entry is used as the reference for crop management practices listed in the operation file, such as planting and harvesting.', 'name', 'NAME', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_n_concn_forage', 'N CONCN FORAGE', 'The N concentration in forage or removed residues at harvest.', NULL, 'N CONCN FORAGE', 'https://w3id.org/okn/i/mint/FORAGE-OR-RESIDUE~REMOVED_NITROGEN__MASS_FRACTION', 'https://w3id.org/okn/i/mint/%25') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_n_dilution_slope', 'N_DILUTION_SLOPE', 'A parameter that controls the slope of the N dilution curve, which regulates crop N requirements as biomass accrues.', NULL, 'N_DILUTION_SLOPE', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_net_mineraliz', 'NET MINERALIZ', 'Net N mineralization.', NULL, 'NET MINERALIZ', 'https://w3id.org/okn/i/mint/NITROGEN__MASS-PER-AREA_MINERALIZATION_DENSITY', 'https://w3id.org/okn/i/mint/kg+ha-1') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_n_fixation', 'N FIXATION', 'Cumulative N fixation by legume crops.', NULL, 'N FIXATION', 'https://w3id.org/okn/i/mint/CROPS~LEGUME_NITROGEN__MASS-PER-AREA_FIXATION_DENSITY', 'https://w3id.org/okn/i/mint/kg+ha-1') ON CONFLICT DO NOTHING;
