INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_n_in_harvest', 'N IN HARVEST', 'N content in removed biomass; which is the sum of grain; forage; and/or removed residues.', NULL, 'N IN HARVEST', 'https://w3id.org/okn/i/mint/BIOMASS~REMOVED_NITROGEN__MASS-PER-AREA_DENSITY', 'https://w3id.org/okn/i/mint/kg+ha-1') ON CONFLICT DO NOTHING;
