INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_optimum_temperature_for_development', 'OPTIMUM_TEMPERATURE_FOR_DEVELOPMENT', 'When air temperatures are above this value (degree C) and below MAX_TEMPERATURE_FOR_DEVELOPMENT, the accumulation of thermal time is calculated as (MAX_TEMPERATURE_FOR_DEVELOPMENT â€“ air temperature) / (MAX_TEMPERATURE_FOR_DEVELOPMENT - OPTIMUM_TEMPERATURE_FOR_DEVELOPMENT) * (OPTIMUM_TEMPERATURE_FOR_DEVELOPMENT â€“ BASE_TEMPERATURE_FOR_DEVELOPMENT)', NULL, 'OPTIMUM_TEMPERATURE_FOR_DEVELOPMENT', NULL, 'https://w3id.org/okn/i/mint/degCTe') ON CONFLICT DO NOTHING;
INSERT INTO public.modelcatalog_variable_presentation (id, label, description, has_long_name, has_short_name, has_standard_variable, uses_unit) VALUES ('https://w3id.org/okn/i/mint/cycles_org_soil_n', 'ORG SOIL N', 'The sum of microbial biomass N and stabilized soil organic N pools.', NULL, 'ORG SOIL N', 'https://w3id.org/okn/i/mint/BIOMASS~MICROBIAL-AND-SOIL_POOL~ORGANIC~STABILIZED-AS-NITROGEN__MASS-PER-AREA_DENSITY', 'https://w3id.org/okn/i/mint/kg+ha-1') ON CONFLICT DO NOTHING;
